-- systematic: every non-party PAC (FEC type O,Q,N,V,W,U) with 100+ of the 19's donors; share of its whole itemized donor list that also gave to the 19. 
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5)||IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$'))
   ||LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) kk
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
c AS (SELECT CMTE_ID, ANY_VALUE(CMTE_NM) nm, ANY_VALUE(CMTE_TP) tp, ANY_VALUE(TRES_NM) tres, ANY_VALUE(CMTE_CITY||' '||CMTE_ST) city FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES GROUP BY 1),
f AS (SELECT i.CMTE_ID, LEFT(ZIP_CODE,5)||TRIM(SPLIT_PART(DONOR_NAME,',',1))||LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) kk
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS i JOIN c ON c.CMTE_ID=i.CMTE_ID AND c.tp IN ('O','Q','N','V','W','U')
  WHERE COALESCE(MEMO_CD,'')<>'X'),
t AS (SELECT CMTE_ID, COUNT(DISTINCT kk) donors, COUNT(DISTINCT IFF(kk IN (SELECT kk FROM s), kk, NULL)) d19 FROM f GROUP BY 1)
SELECT t.*, ROUND(100*d19/donors,1) pct_in19, c.nm, c.tp, c.tres, c.city FROM t JOIN c USING (CMTE_ID) WHERE d19 >= 100 ORDER BY pct_in19 DESC LIMIT 40
